INSERT INTO faq (question, answer, category_id, search_keywords, display_order, is_active) VALUES ('How do I delete my account?', 'You can request account deletion through the Help & Support section in your profile. Navigate to your profile, open Help & Support, and select the "Delete Account" tab. Once you submit a deletion request, your account will be permanently deleted within 7-10 business days. You will receive an email confirmation once your account has been successfully deleted. Please note that this action is irreversible — all your personal data, profile information, collaborations, messages, and associated content will be permanently removed.', '7553314d-c9d7-4d76-85d5-37cb05303f1b', ARRAY['delete', 'account', 'remove', 'close account', 'deactivate', 'deletion'], 3, true);